/* ---------- SVG बनाने के छोटे हेल्पर ---------- */
var SVF = 'Noto Sans Devanagari, sans-serif';
var SVM = 'IBM Plex Mono, monospace';
function SVfig(svg, cap) {
  /* सेक्शन रेंडरर ख़ुद <figure class="diagram"> लगाता है — यहाँ केवल SVG + caption */
  return svg + (cap ? '<figcaption>' + cap + '</figcaption>' : '');
}
function SVdefs(id, color) {
  return '<defs><marker id="' + id + '" markerWidth="10" markerHeight="8" refX="9" refY="4" orient="auto">' +
    '<path d="M0,0 L10,4 L0,8 z" fill="' + (color || '#38bdf8') + '"/></marker></defs>';
}
function SVbox(x, y, w, h, t1, t2, fill, stroke, fs) {
  return '<g><rect x="' + x + '" y="' + y + '" width="' + w + '" height="' + h + '" rx="12" fill="' + fill + '" stroke="' + stroke + '" stroke-width="2"/>' +
    '<text x="' + (x + w / 2) + '" y="' + (y + h / 2 + (t2 ? -3 : 6)) + '" text-anchor="middle" fill="#e8eefc" font-size="' + (fs || 15) + '" font-weight="700" font-family="' + SVF + '">' + t1 + '</text>' +
    (t2 ? '<text x="' + (x + w / 2) + '" y="' + (y + h / 2 + 17) + '" text-anchor="middle" fill="#9fb6d6" font-size="11.5" font-family="' + SVF + '">' + t2 + '</text>' : '') +
    '</g>';
}
function SVsmall(x, y, w, h, t, fill, stroke, fs) {
  return '<g><rect x="' + x + '" y="' + y + '" width="' + w + '" height="' + h + '" rx="8" fill="' + fill + '" stroke="' + stroke + '" stroke-width="1.6"/>' +
    '<text x="' + (x + w / 2) + '" y="' + (y + h / 2 + 4) + '" text-anchor="middle" fill="#cfe3ff" font-size="' + (fs || 11.5) + '" font-weight="600" font-family="' + SVF + '">' + t + '</text></g>';
}
function SVline(x1, y1, x2, y2, label, color, arrow, mid, dash) {
  return '<line x1="' + x1 + '" y1="' + y1 + '" x2="' + x2 + '" y2="' + y2 + '" stroke="' + (color || '#38bdf8') + '" stroke-width="2.2"' +
    (arrow ? ' marker-end="url(#' + arrow + ')"' : '') + (dash ? ' stroke-dasharray="6 5"' : '') + '/>' +
    (label ? '<text x="' + ((mid != null) ? mid : (x1 + x2) / 2) + '" y="' + ((y1 + y2) / 2 - 7) + '" text-anchor="middle" fill="' + (color || '#7dd3fc') + '" font-size="11.5" font-family="' + SVF + '">' + label + '</text>' : '');
}
function SVtxt(x, y, t, color, fs, anchor, weight) {
  return '<text x="' + x + '" y="' + y + '" text-anchor="' + (anchor || 'middle') + '" fill="' + (color || '#9fb6d6') + '" font-size="' + (fs || 12.5) + '" font-weight="' + (weight || 600) + '" font-family="' + SVF + '">' + t + '</text>';
}

/* ---------- डायग्राम S1 : ESD सुरक्षा के 5 स्तर ---------- */
/* window.SVdiagSafety -> app.js का alias "SVsafety" */
window.SVdiagSafety = function SVdiagSafety() {
  var s = '<svg viewBox="0 0 900 540" xmlns="http://www.w3.org/2000/svg">' + SVdefs('svs1', '#f472b6');
  s += SVtxt(450, 26, 'स्टैटिक (ESD) कहाँ से आता है और उसे रोकने के 5 स्तर', '#94a3c4', 13.5);
  /* बाएँ : स्रोत */
  s += SVbox(20, 48, 250, 44, 'स्टैटिक के स्रोत', 'रगड़ से चार्ज अलग होना — Triboelectric', '#2a1c31', '#f472b6', 13);
  var src = [['कारपेट पर चलना', '1,500 – 35,000 V', '#ef4444'],
             ['कुर्सी से उठना', '1,000 – 15,000 V', '#f97316'],
             ['प्लास्टिक बैग खोलना', '1,000 – 20,000 V', '#f97316'],
             ['विनाइल फ़र्श पर चलना', '250 – 12,000 V', '#facc15'],
             ['काग़ज़ खिसकाना', '700 – 6,000 V', '#facc15']];
  src.forEach(function (r, i) {
    var y = 108 + i * 54;
    s += SVsmall(20, y, 150, 40, r[0], '#1b2233', '#3b4a63', 11.5);
    s += SVsmall(178, y, 92, 40, r[1], '#2b1a22', r[2], 11.5);
  });
  s += SVtxt(145, 384, 'चिप के लिए ख़तरा: केवल 20–30 V', '#f472b6', 12.5);
  s += SVtxt(145, 404, '(इसलिए “मुझे तो कुछ महसूस ही नहीं हुआ” वाली बात जोखिम भरी है)', '#8fa6c4', 11);
  /* दाएँ : 5 स्तर */
  s += SVbox(300, 48, 580, 44, 'सुरक्षा के 5 स्तर', 'एक भी स्तर छूटा तो ESD का रास्ता खुला', '#152238', '#38bdf8', 13);
  var lv = [
    ['1', 'शरीर', 'ESD स्ट्रैप + ग्राउंड कॉर्ड · रबर सोल जूते · कपास के कपड़े', '#22c55e'],
    ['2', 'कार्यक्षेत्र', 'ESD मैट या लकड़ी/कार्डबोर्ड · नायलॉन-प्लास्टिक चादर वर्जित', '#22d3ee'],
    ['3', 'औज़ार', 'ग्राउंडेड सोल्डरिंग आयरन · एंटीस्टैटिक ब्रश · प्लास्टिक स्पडर', '#3b82f6'],
    ['4', 'पुर्ज़ा', 'एंटीस्टैटिक बैग/ट्रे · बोर्ड बैग के ऊपर, सीधे टेबल पर नहीं', '#a78bfa'],
    ['5', 'वातावरण', '40–60% आर्द्रता · AC की ठंडी सूखी हवा सीधे बोर्ड पर नहीं', '#facc15']
  ];
  lv.forEach(function (r, i) {
    var y = 106 + i * 58;
    s += '<rect x="300" y="' + y + '" width="580" height="48" rx="10" fill="#101827" stroke="' + r[3] + '" stroke-width="1.8"/>';
    s += '<circle cx="330" cy="' + (y + 24) + '" r="16" fill="' + r[3] + '" opacity="0.22" stroke="' + r[3] + '"/>';
    s += SVtxt(330, y + 29, r[0], r[3], 14, 'middle', 700);
    s += SVtxt(356, y + 22, r[1], '#e8eefc', 13, 'start', 700);
    s += SVtxt(356, y + 39, r[2], '#9fb6d6', 11, 'start', 500);
  });
  s += SVtxt(590, 414, 'लक्ष्य: शरीर और बोर्ड — दोनों का विभव (potential) एक ही स्तर पर', '#7dd3fc', 12.5);
  s += SVsmall(300, 440, 580, 62, 'छुपा हुआ नुकसान (Latent Damage): ESD से चिप आज पूरी तरह नहीं मरती — गेट ऑक्साइड पतला हो जाता है और 2–3 महीने बाद अचानक फेल होती है। यही सबसे ख़तरनाक है, क्योंकि इल्ज़ाम आप पर आता है।', '#221a10', '#f59e0b', 11.5);
  return s + '</svg>';
};

/* ---------- डायग्राम S2 : डिसअसेंबली का क्रम (उलटा पिरामिड) ---------- */
/* window.SVdiagTeardown -> app.js का alias "SVteardown" */
window.SVdiagTeardown = function SVdiagTeardown() {
  var s = '<svg viewBox="0 0 900 560" xmlns="http://www.w3.org/2000/svg">' + SVdefs('svt1', '#22c55e');
  s += SVtxt(450, 26, 'डिसअसेंबली — ऊपर से नीचे, यानी बाहर से अंदर (LIFO क्रम)', '#94a3c4', 13.5);
  var groups = [
    ['समूह A · तैयारी', 'स्ट्रैप · औज़ार · कंटेनर · फ़ोटो/रजिस्टर · पावर पूरी तरह काटना', '#f472b6'],
    ['समूह B · बाहरी तार', 'फ्रंट पैनल के पतले तार → SATA डेटा → फैन → 24-pin → CPU 8-pin → PCIe', '#facc15'],
    ['समूह C · अड-ऑन व ड्राइव', 'GPU/कार्ड → HDD/SSD/M.2 → SMPS (ठंडा होकर)', '#fb923c'],
    ['समूह D · बोर्ड का कोर', 'कूलर/पंप → RAM → मदरबोर्ड स्क्रू → CPU (लीवर) → जंपर/बैटरी नोट', '#22c55e'],
    ['समूह E · सुरक्षित रखना', 'सफ़ाई · निरीक्षण (फूला कैपेसिटर/जला MOSFET) · लेबल व ESD बैग में पैकिंग', '#22d3ee']
  ];
  groups.forEach(function (g, i) {
    var w = 800 - i * 60, x = 50 + i * 30, y = 54 + i * 96;
    s += '<rect x="' + x + '" y="' + y + '" width="' + w + '" height="76" rx="14" fill="#101827" stroke="' + g[2] + '" stroke-width="2"/>';
    s += SVtxt(x + 16, y + 30, g[0], g[2], 13.5, 'start', 700);
    s += SVtxt(x + 16, y + 54, g[1], '#b6c7de', 11.5, 'start', 500);
    if (i < groups.length - 1) s += SVline(450, y + 76, 450, y + 96, '', '#4b5f7d', 'svt1');
  });
  s += SVtxt(760, 466, 'नियम: तार पहले, हार्डवेयर बाद', '#7dd3fc', 12.5);
  s += SVtxt(450, 534, 'असेंबली इसी सूची का उल्टा क्रम है — इसलिए डिसअसेंबली सीखना ही असेंबली सीखना है', '#8fa6c4', 12);
  return s + '</svg>';
};

/* ---------- डायग्राम S3 : केस का एयरफ़्लो व धूल ---------- */
/* window.SVdiagAirflow -> app.js का alias "SVairflow" */
window.SVdiagAirflow = function SVdiagAirflow() {
  var s = '<svg viewBox="0 0 900 520" xmlns="http://www.w3.org/2000/svg">' + SVdefs('sva1', '#38bdf8');
  s += SVtxt(450, 26, 'केस का एयरफ़्लो (हवा का रास्ता) और धूल कहाँ जमा होती है', '#94a3c4', 13.5);
  s += '<rect x="150" y="50" width="600" height="400" rx="18" fill="#0d1524" stroke="#2b3a52" stroke-width="2.5"/>';
  /* इनटेक फैन (फ्रंट) */
  s += '<rect x="160" y="150" width="34" height="150" rx="8" fill="#0f2233" stroke="#38bdf8" stroke-width="2"/>';
  s += SVtxt(177, 320, 'फ्रंट इनटेक', '#7dd3fc', 11.5);
  s += SVtxt(177, 338, '120/140mm', '#5f7fa5', 10.5);
  /* फ़िल्टर */
  s += '<rect x="140" y="130" width="14" height="190" rx="5" fill="#1c2b1c" stroke="#4ade80" stroke-width="1.6" stroke-dasharray="5 4"/>';
  s += SVtxt(60, 132, 'धूल फ़िल्टर', '#4ade80', 11.5, 'start');
  /* हीटसिंक */
  s += SVbox(300, 130, 150, 120, 'CPU कूलर', 'हीटसिंक फ़िन में धूल सबसे पहले', '#172a1f', '#22c55e', 13);
  /* GPU */
  s += SVbox(300, 296, 200, 66, 'GPU कार्ड', 'फैन + हीटसिंक', '#1b2333', '#a78bfa', 12.5);
  /* PSU */
  s += SVbox(600, 330, 130, 90, 'SMPS', 'अंदर की धूल = शॉर्ट/आग', '#2b2416', '#f59e0b', 12.5);
  /* रियर + टॉप आउटटेक */
  s += '<rect x="700" y="140" width="34" height="130" rx="8" fill="#2a1517" stroke="#f87171" stroke-width="2"/>';
  s += SVtxt(717, 292, 'रियर', '#f87171', 11);
  s += '<rect x="430" y="52" width="150" height="26" rx="8" fill="#2a1517" stroke="#f87171" stroke-width="2"/>';
  s += SVtxt(505, 96, 'टॉप आउटटेक', '#f87171', 11);
  /* तीर */
  s += SVline(200, 226, 292, 200, 'ठंडी हवा', '#38bdf8', 'sva1');
  s += SVline(455, 190, 696, 200, 'गर्म हवा', '#f87171', 'sva1');
  s += SVline(380, 366, 594, 376, 'PSU की अपनी हवा', '#f59e0b', 'sva1');
  s += SVtxt(490, 232, 'हवा का रास्ता खुला रखिए — केबल उसमें न लटकाएँ', '#8fa6c4', 11.5);
  s += SVsmall(150, 462, 600, 44, 'सकारात्मक दबाव (इनटेक ज़्यादा) = धूल कम, फ़िल्टर से आती है। नकारात्मक दबाव = ठंडक बेहतर, मगर धूल हर जोड़ से अंदर। धूल भरी लैब में सकारात्मक दबाव चुनिए।', '#122036', '#38bdf8', 11.5);
  return s + '</svg>';
};

